# Let's use the SAT solver properly
from pysat.solvers import Solver

n = 15
seq_len = 30

fixed = {
    3: 2,
    11: 14,
    13: 11,
    26: 14,
    27: 7,
    28: 10
}

# Create a SAT solver
solver = Solver(name='glucose3')

# Variable encoding: for each value v (1..15) and each possible start position p,
# create a variable. The variable is True if value v starts at position p.
# Start position p means v is at positions p and p+v+1.

var = {}  # (v, p) -> variable id
var_id = 1
for v in range(1, n+1):
    for p in range(0, seq_len - (v+1)):
        p2 = p + v + 1
        if p2 < seq_len:
            var[(v, p)] = var_id
            var_id += 1

print(f"Total variables: {var_id-1}")

# Each value must have exactly one start position
for v in range(1, n+1):
    vars_for_v = [var[(v, p)] for p in range(0, seq_len - (v+1)) if p + v + 1 < seq_len]
    # At least one
    solver.add_clause(vars_for_v)
    # At most one (pairwise)
    for i in range(len(vars_for_v)):
        for j in range(i+1, len(vars_for_v)):
            solver.add_clause([-vars_for_v[i], -vars_for_v[j]])

# Each position can have at most one value
for pos in range(seq_len):
    vars_at_pos = []
    for v in range(1, n+1):
        for p in range(0, seq_len - (v+1)):
            p2 = p + v + 1
            if p2 < seq_len:
                if p == pos or p2 == pos:
                    vars_at_pos.append(var[(v, p)])
    # At most one value at this position
    for i in range(len(vars_at_pos)):
        for j in range(i+1, len(vars_at_pos)):
            solver.add_clause([-vars_at_pos[i], -vars_at_pos[j]])

# Each position must have at least one value
for pos in range(seq_len):
    vars_at_pos = []
    for v in range(1, n+1):
        for p in range(0, seq_len - (v+1)):
            p2 = p + v + 1
            if p2 < seq_len:
                if p == pos or p2 == pos:
                    vars_at_pos.append(var[(v, p)])
    solver.add_clause(vars_at_pos)

# Fixed assignments
for pos, val in fixed.items():
    clauses_for_fixed = []
    # Option 1: pos is first occurrence (start at pos)
    if pos + val + 1 < seq_len:
        clauses_for_fixed.append(var[(val, pos)])
    # Option 2: pos is second occurrence (start at pos-val-1)
    start = pos - (val + 1)
    if start >= 0 and start + val + 1 < seq_len:
        clauses_for_fixed.append(var[(val, start)])
    # Must be one of these
    solver.add_clause(clauses_for_fixed)

print("Solving...")
result = solver.solve()
print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    # Decode
    seq = [0] * seq_len
    for (v, p), var_idx in var.items():
        if model[var_idx-1] > 0:
            seq[p] = v
            seq[p+v+1] = v

    print("Solution:", seq)

    # Verify
    for v in range(1, n+1):
        positions = [i for i, x in enumerate(seq) if x == v]
        assert len(positions) == 2, f"Value {v} appears {len(positions)} times"
        assert positions[1] - positions[0] == v + 1, f"Value {v} distance is {positions[1] - positions[0]}, expected {v+1}"

    for pos, val in fixed.items():
        assert seq[pos] == val, f"Fixed position {pos} has {seq[pos]}, expected {val}"

    print("Verification passed!")
else:
    print("UNSATISFIABLE")
